CREATE TEMPORARY VIEW dim_item_${grass_region_without_quote} AS 
SELECT
     item_id
    ,shop_id
    ,global_be_category_id
    ,level1_global_be_category_id
    ,level2_global_be_category_id
    ,level3_global_be_category_id
    ,level4_global_be_category_id
    ,level5_global_be_category_id
    ,global_be_category
    ,level1_global_be_category
    ,level2_global_be_category
    ,level3_global_be_category
    ,level4_global_be_category
    ,level5_global_be_category
    ,price_usd AS price
    ,price AS price_local
    ,price_before_discount_usd AS price_before_discount
    ,price_before_discount AS price_before_discount_local
    ,price_max_usd AS item_price_max
    ,price_max AS item_price_max_local
    ,rating_score AS item_rating_score
    ,rating_total_cnt AS item_rating_total_cnt
    ,global_brand_details.name AS item_global_brand
    ,global_brand_details.id AS item_global_brand_id
    ,status AS item_status
    ,mtsku_item_id
    ,create_datetime AS item_create_datetime
    ,name as item_name
    ,discount_pct
    ,sold_cnt as item_sold_cnt
    ,CASE WHEN is_free_shipping = 1 THEN TRUE ELSE FALSE END AS is_free_shipping
    ,CASE WHEN is_official_shop = 1 THEN TRUE ELSE FALSE END AS is_official_shop
    ,CASE WHEN is_cb_shop = 1 THEN TRUE ELSE FALSE END AS is_cb_shop
    ,comment_cnt
    ,estimated_days_to_ship
    ,is_cod
    ,is_domestic_stocked
    ,is_sbs
    ,is_pre_order
    ,split(kpi_categories[0][0], ':')[1] AS kpi_level1_category
    ,coalesce(split(kpi_categories[0][1], ':')[1], 'N/A') AS kpi_level2_category
    ,coalesce(split(kpi_categories[0][2], ':')[1], 'N/A') AS kpi_level3_category
    ,grass_region
    ,create_timestamp as item_create_timestamp
FROM
    mp_item.dim_item__reg_s0_live
where tz_type = 'local'
      AND grass_date = ${local_date}
      AND grass_region IN (${grass_region});

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_item_ext_${grass_region_without_quote} AS
SELECT
     item_id, images, is_cb_shop
FROM
    mp_item.dim_item_ext__reg_s0_live
where tz_type = 'local'
       AND grass_date = ${local_date}
       AND grass_region IN (${grass_region});

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_high_gmv_cate_${grass_region_without_quote} AS
SELECT
    transform(split(trim(translate(category, '[]', '')), ','), x->trim(x)) AS high_gmv_category
FROM 
(   
    SELECT
        *
        ,row_number() over (partition by grass_region order by update_date desc) as rn
    FROM 
        srdi_mart.dim_sr_data_warehouse_high_gmv_category
    WHERE
        grass_region = ${grass_region}
)
WHERE
    rn = 1
;

--sql_divide_splitter--

CREATE TEMPORARY VIEW dim_item_merged_${grass_region_without_quote} AS
SELECT      
/*+ BROADCASTJOIN(c)*/
            a.item_id
           ,a.shop_id
           ,a.global_be_category_id
           ,a.level1_global_be_category_id
           ,a.level2_global_be_category_id
           ,a.level3_global_be_category_id
           ,a.level4_global_be_category_id
           ,a.level5_global_be_category_id
           ,a.global_be_category
           ,a.level1_global_be_category
           ,a.level2_global_be_category
           ,a.level3_global_be_category
           ,a.level4_global_be_category
           ,a.level5_global_be_category
           ,a.price
           ,a.price_local
           ,a.price_before_discount
           ,a.price_before_discount_local
           ,a.item_price_max
           ,a.item_price_max_local
           ,a.item_rating_score
           ,a.item_rating_total_cnt
           ,a.item_global_brand
           ,a.item_global_brand_id
           ,a.item_status
           ,a.mtsku_item_id
           ,a.item_create_datetime
           ,a.item_name
           ,a.discount_pct
           ,a.item_sold_cnt
           ,a.is_cb_shop
           ,a.is_official_shop
           ,a.is_free_shipping
           ,b.images
           ,a.comment_cnt
           ,a.estimated_days_to_ship
           ,a.is_cod
           ,a.is_domestic_stocked
           ,a.is_sbs
           ,a.is_pre_order
           ,NULL as local_l0_cat
           ,NULL as local_l1_cat
           ,if(array_contains(high_gmv_category, a.level1_global_be_category), 'high gmv', 'low gmv') AS category_tag
           ,a.item_create_timestamp
FROM dim_item_${grass_region_without_quote} a
LEFT JOIN dim_item_ext_${grass_region_without_quote} b
ON a.item_id = b.item_id and a.is_cb_shop = b.is_cb_shop
LEFT JOIN dim_high_gmv_cate_${grass_region_without_quote} c
;

